CREATE TABLE IF NOT EXISTS episodic_memory (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id TEXT NOT NULL, show_slug TEXT, role TEXT NOT NULL CHECK(role IN ('user','agent','system')), content TEXT NOT NULL, timestamp DATETIME DEFAULT CURRENT_TIMESTAMP, importance_score REAL DEFAULT 0.5, decay_factor REAL DEFAULT 1.0);
CREATE INDEX IF NOT EXISTS idx_episodic_session_time ON episodic_memory(session_id,timestamp);
CREATE TABLE IF NOT EXISTS semantic_memory (id INTEGER PRIMARY KEY AUTOINCREMENT, concept TEXT NOT NULL UNIQUE, definition TEXT NOT NULL, source TEXT, confidence REAL DEFAULT 0.8, last_accessed DATETIME DEFAULT CURRENT_TIMESTAMP, access_count INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS procedural_memory (id INTEGER PRIMARY KEY AUTOINCREMENT, procedure_name TEXT NOT NULL UNIQUE, description TEXT NOT NULL, success_rate REAL DEFAULT 0.0, invocation_count INTEGER DEFAULT 0, last_used DATETIME, prompt_template TEXT);
CREATE TABLE IF NOT EXISTS narrative_memory (id INTEGER PRIMARY KEY AUTOINCREMENT, show_slug TEXT, chapter TEXT NOT NULL, summary TEXT NOT NULL, key_events TEXT, emotional_tone TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS autonomous_goals (id INTEGER PRIMARY KEY AUTOINCREMENT, show_slug TEXT, goal_title TEXT NOT NULL, goal_description TEXT NOT NULL, standing_order TEXT, schedule_cron TEXT, status TEXT DEFAULT 'active' CHECK(status IN ('active','paused','completed','failed')), progress REAL DEFAULT 0.0, last_run DATETIME, next_run DATETIME, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS content_jobs (id INTEGER PRIMARY KEY AUTOINCREMENT, show_slug TEXT NOT NULL, topic TEXT NOT NULL, script TEXT, status TEXT DEFAULT 'pending' CHECK(status IN ('pending','script_ready','tts_complete','video_ready','uploaded','failed')), github_run_id TEXT, video_url TEXT, youtube_video_id TEXT, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, completed_at DATETIME);
CREATE INDEX IF NOT EXISTS idx_content_status ON content_jobs(status,created_at);
CREATE TABLE IF NOT EXISTS dynamic_tools (id INTEGER PRIMARY KEY AUTOINCREMENT, tool_name TEXT NOT NULL UNIQUE, prompt_template TEXT NOT NULL, ttl_days INTEGER DEFAULT 30, use_count INTEGER DEFAULT 0, auto_promoted INTEGER DEFAULT 0, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS rate_limits (api_key TEXT NOT NULL, date TEXT NOT NULL, count INTEGER DEFAULT 0, PRIMARY KEY(api_key,date));
CREATE TABLE IF NOT EXISTS daily_stats (date TEXT PRIMARY KEY, scripts_generated INTEGER DEFAULT 0, videos_rendered INTEGER DEFAULT 0, videos_uploaded INTEGER DEFAULT 0, neurons_used INTEGER DEFAULT 0, errors INTEGER DEFAULT 0, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS shows (id INTEGER PRIMARY KEY AUTOINCREMENT, show_slug TEXT NOT NULL UNIQUE, show_name TEXT NOT NULL, tone TEXT NOT NULL, target_demographic TEXT NOT NULL, primary_platforms TEXT NOT NULL, rpm_range TEXT NOT NULL, recurring_offer_name TEXT NOT NULL, recurring_offer_price TEXT NOT NULL, youtube_playlist_id TEXT DEFAULT '', youtube_show_id TEXT DEFAULT '', status TEXT DEFAULT 'active', created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS payments (id INTEGER PRIMARY KEY AUTOINCREMENT, reference TEXT NOT NULL UNIQUE, event TEXT NOT NULL, email TEXT, amount INTEGER, currency TEXT, status TEXT NOT NULL, payload TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP);
